data.script:
frappe.ui.form.on('Task', {
	refresh(frm) {
		frappe.call({
		    method:"frappe.client.get_value",
		    args:{
		        doctype:"Timesheet",
		        filters:{
		            Task:doc.name
		        },
		        fieldname:"total_hours"
		    },
		    callback:function(idResponse){
		        if(idResponse)
		        doc.efforts=idResponse.message.totalhours
		    }
		})
	}
})
